-- Digital Technology and Computer Applications final module. Run seed_dt_course.sql first. Safe to run more than once.

do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'digital-technology';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 7, $j$Final Assessment: My Digital Technology Portfolio and Reflection$j$, $j${"prompt": "Create a digital technology portfolio plan and reflection of at least 700 words. Use your own work, or realistic examples you create for this course. Do not include passwords, private account details, your home address or other people's private information, and ask a parent, guardian or teacher to review your work. Include lists or tables where they help. Proverbs 16:3 says, Commit thy works unto the LORD, and thy thoughts shall be established.\n\nPart 1: Computers and Files. Explain the parts of a computer and the computing cycle. Describe your folder system, file naming and backup plan.\nPart 2: Documents. Type a short professional email or letter of at least six sentences, and list the formatting choices you would use in a school paper.\nPart 3: Spreadsheet. Describe a spreadsheet you would build for a church, family or school budget or record. Give column headings, three sample rows, two formulas or functions and the best chart for the data.\nPart 4: Presentation. Outline a six slide presentation with a title and one main idea for each slide, and give four design and delivery tips.\nPart 5: Internet and Security. Explain HTTPS, strong passwords and multifactor authentication, and give a security plan for your devices. Describe how to recognize a phishing message and how to use AI tools honestly.\nPart 6: Computational Thinking and Web. Write an algorithm in numbered steps or pseudocode with a decision and a loop. Write a short HTML page idea with a title, heading, paragraph and link.\nPart 7: Media, Careers and Ministry. Describe how you would create and share media safely, name two technology careers you are exploring and a certification or pathway for each, and explain how technology can serve a ministry.\nPart 8: Faith and Reflection. Apply at least three Scripture passages from the King James Version to your use of technology, and write a reflection on what you learned, what you will improve and your goal for the next year.", "rubric": "100 points. Part 1, computers and files: 10 points. Part 2, documents: 10 points. Part 3, spreadsheet: 15 points. Part 4, presentation: 10 points. Part 5, internet and security: 15 points. Part 6, computational thinking and web: 15 points. Part 7, media, careers and ministry: 10 points. Part 8, faith and reflection: 10 points. Grammar, conventions and accuracy: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Final Assessment: My Digital Technology Portfolio and Reflection$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 31, $j$Final Exam: Digital Technology and Computer Applications$j$, $j${"questions": [{"q": "The brain of the computer that carries out instructions is the:", "options": ["CPU", "Keyboard", "Monitor", "Printer"]}, {"q": "Short term working memory that clears when the power is off is:", "options": ["A router", "A solid state drive", "RAM", "A file extension"]}, {"q": "Software that manages the hardware and files of a computer is the:", "options": ["Spell checker", "Printer", "Operating system", "Cable"]}, {"q": "A strong password is generally:", "options": ["Long and unique", "The word password", "Short and shared", "A birthday"]}, {"q": "The record of everything you post and click online is your:", "options": ["Firewall", "Cell range", "Backup", "Digital footprint"]}, {"q": "In a spreadsheet, the cell reference for column B, row 4 is:", "options": ["4B column", "R4", "B4", "BB4"]}, {"q": "The function that adds a range of numbers is:", "options": ["IF", "MIN", "SUM", "COUNT only"]}, {"q": "The best chart for change over time is a:", "options": ["Photograph", "Pie chart", "Line chart", "Table of contents"]}, {"q": "The Domain Name System turns names into:", "options": ["Photos", "Fonts", "IP addresses", "Passwords"]}, {"q": "Fake messages that trick people into giving passwords are:", "options": ["Backups", "Packets", "Updates", "Phishing"]}, {"q": "A step by step set of instructions to solve a problem is an:", "options": ["Algorithm", "Pixel", "Router", "Operating system"]}, {"q": "The language that gives a web page its structure is:", "options": ["VPN", "CSS", "HTML", "WPA3"]}, {"q": "An image type that can be resized without losing quality is:", "options": ["Raster", "Blurred", "Compressed only", "Vector"]}, {"q": "1 Thessalonians 5:21 says to prove all things and:", "options": ["Share rumors", "Believe everything", "Avoid learning", "Hold fast that which is good"]}, {"q": "Matthew 7:12 teaches us to do to others:", "options": ["What we would want done to us", "Nothing", "Whatever is easiest", "What others do to us"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Digital Technology and Computer Applications$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,2,0,3,2,2,2,2,3,0,2,3,3,0}'::int[], array[$j$The CPU processes instructions.$j$,$j$RAM is temporary.$j$,$j$The OS manages the machine.$j$,$j$Length and uniqueness protect accounts.$j$,$j$It can last for years.$j$,$j$Column letter then row number.$j$,$j$SUM totals a range.$j$,$j$Line charts show trends.$j$,$j$DNS works like a phone book.$j$,$j$Phishing uses deception.$j$,$j$That is an algorithm.$j$,$j$HTML structures the page.$j$,$j$Vector graphics scale cleanly.$j$,$j$Test information before trusting it.$j$,$j$The golden rule guides our online conduct.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Digital Technology and Computer Applications$j$ on conflict (item_id) do nothing;
end
$seed$;
